files.src/state/store.js:
module.exports = () => {
  let state = "idle";
  return { get: () => state, set: (next) => { state = next; } };
};

files.src/ui/view.js:
module.exports = (store) => {
  const label = store.get();
  return { label: () => label };
};

patch:
--- a/src/state/store.js
+++ b/src/state/store.js
@@ -1,4 +1,9 @@
-module.exports = () => {
-  let state = "idle";
-  return { get: () => state, set: (next) => { state = next; } };
-};
+module.exports = () => {
+  let state = "idle";
+  const listeners = [];
+  return {
+    get: () => state,
+    set: (next) => { state = next; listeners.forEach((listener) => listener(next)); },
+    subscribe: (listener) => { listeners.push(listener); },
+  };
+};
--- a/src/ui/view.js
+++ b/src/ui/view.js
@@ -1,4 +1,5 @@
-module.exports = (store) => {
-  const label = store.get();
-  return { label: () => label };
-};
+module.exports = (store) => {
+  let label = store.get();
+  store.subscribe((next) => { label = next; });
+  return { label: () => label };
+};

